  test("rates effective dated scenario 3", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "7.50", "from": "2026-03-16"})).toBe(true);
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
    expect(await ui.editPerson(pg_uma, p_ben, {"grade": "C"})).toBe(true);
    const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "12.50", "date": "2026-04-02"}));
    const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "0.04", "date": "2026-03-28"}));
    expect(await ui.claimAction(pg_uma, c_cam_0, "void")).toBe(true);
    const c_cam_1 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "0.04"}));
    expect(await ui.claimAction(pg_uma, c_ben_0, "void")).toBe(true);
    const c_cam_2 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "4.00"}));
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("0.00");
    expect(await ui.editPerson(pg_uma, p_ben, {"grade": "B"})).toBe(true);
    expect(await ui.editPerson(pg_uma, p_cam, {"grade": "A"})).toBe(true);
    expect(await ui.editPerson(pg_uma, p_cam, {"grade": "C"})).toBe(true);
    const c_cam_3 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "10.25", "date": "2026-03-15"}));
    const c_ben_1 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "10.25", "date": "2026-04-02"}));
    await ui.setToday(pg_uma, "2026-04-17");
    const c_ben_2 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "7.77", "date": "2026-03-28"}));
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("0.00");
    expect(await ui.claimAction(pg_uma, c_cam_2, "open")).toBe(true);
    await ui.setToday(pg_uma, "2026-05-03");
    expect(await ui.claimAction(pg_uma, c_cam_3, "open")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_cam_1, "open")).toBe(true);
    await ui.setToday(pg_uma, "2026-06-01");
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    expect(await ui.claimAction(pg_wes, c_cam_3, "settle")).toBe(true);
    expect(await ui.editPerson(pg_wes, p_ben, {"grade": "A"})).toBe(true);
    await ui.refresh(pg_wes);
    await expect(pg_wes.getByTestId("rollup-claimed-total")).toHaveText("14.29");
    await expect(pg_wes.getByTestId("rollup-due-total")).toHaveText("1.07");
    const c_cam_4 = ui.must(await ui.addClaim(pg_wes, p_cam, {"amount": "4.00", "date": "2026-03-01"}));
    await ui.refresh(pg_wes);
    await expect(pg_wes.getByTestId("rollup-claimed-total")).toHaveText("14.29");
    await expect(pg_wes.getByTestId("rollup-due-total")).toHaveText("1.07");
    await expect(pg_wes.getByTestId("rate-current-A")).toHaveText("12.50");
    await expect(pg_wes.getByTestId("rate-current-B")).toHaveText("7.50");
    await expect(pg_wes.getByTestId("rate-current-C")).toHaveText("7.50");
    await ui.expectAudit(sheet, [
      `RATE_SET sheet=${sheet} by=uma grade=A rate=12.50`,
      `RATE_SET sheet=${sheet} by=uma grade=B rate=7.50`,
      `RATE_SET sheet=${sheet} by=uma grade=C rate=7.50 from=2026-03-16`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ben grade=B`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Cam grade=C`,
      `PERSON_EDITED sheet=${sheet} by=uma name=Ben grade=C`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ben amount=12.50 date=2026-04-02`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Cam amount=0.04 date=2026-03-28`,
      `CLAIM_VOIDED sheet=${sheet} by=uma person=Cam amount=0.04 date=2026-03-28`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Cam amount=0.04 date=2026-03-10`,
      `CLAIM_VOIDED sheet=${sheet} by=uma person=Ben amount=12.50 date=2026-04-02`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Cam amount=4.00 date=2026-03-10`,
      `PERSON_EDITED sheet=${sheet} by=uma name=Ben grade=B`,
      `PERSON_EDITED sheet=${sheet} by=uma name=Cam grade=A`,
      `PERSON_EDITED sheet=${sheet} by=uma name=Cam grade=C`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Cam amount=10.25 date=2026-03-15`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ben amount=10.25 date=2026-04-02`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ben amount=7.77 date=2026-03-28`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Cam amount=4.00 date=2026-03-10 number=1`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Cam amount=10.25 date=2026-03-15 number=2`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Cam amount=0.04 date=2026-03-10 number=3`,
      `CLAIM_SETTLED sheet=${sheet} by=wes person=Cam amount=10.25 date=2026-03-15 number=2 due=n/a`,
      `PERSON_EDITED sheet=${sheet} by=wes name=Ben grade=A`,
      `CLAIM_ADDED sheet=${sheet} by=wes person=Cam amount=4.00 date=2026-03-01`
    ]);
  });
});

